    27→{{/*
    28→Create chart name and version as used by the chart label.
    29→*/}}
    30→{{- define "elasticsearch-exporter.chart" -}}
    31→{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" | trunc 63 | trimSuffix "-" -}}
    32→{{- end -}}
